fn is_palindrome(text: Vec<char>) -> bool {
    // Helper function to convert ASCII uppercase letters 'A'..'Z'
    // to lowercase 'a'..'z', leave other chars unchanged.
    fn to_ascii_lower(c: char) -> char {
        if ('A'..='Z').contains(&c) {
            // Shift to lowercase by adding 32 (difference in ASCII)
            ((c as u8) + 32) as char
        } else {
            c
        }
    }

    let len = text.len();
    for i in 0..len / 2 {
        if to_ascii_lower(text[i]) != to_ascii_lower(text[len - 1 - i]) {
            return false;
        }
    }

    true
}